CREATE DATABASE IF NOT EXISTS micro_logistics CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE micro_logistics;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS maintenance_records,delivery_events,deliveries,vehicles,drivers,customers,users,roles;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE roles(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(40) UNIQUE NOT NULL) ENGINE=InnoDB;
INSERT INTO roles(name) VALUES('administrator'),('dispatcher'),('finance'),('marketing'),('fleet_manager');
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role_id INT NOT NULL,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(id)) ENGINE=InnoDB;
-- Initial password: ChangeMe123! (hash generated with PHP PASSWORD_DEFAULT below; this placeholder is replaced by setup script)
INSERT INTO users(name,email,password_hash,role_id) VALUES('System Administrator','admin@mlfms.local','$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2.uheWG/igi',1);
CREATE TABLE customers(id INT AUTO_INCREMENT PRIMARY KEY,customer_type ENUM('C2C','B2C','B2B') DEFAULT 'C2C',name VARCHAR(150) NOT NULL,phone VARCHAR(30) NOT NULL,email VARCHAR(190),business_name VARCHAR(150),billing_address TEXT,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(phone)) ENGINE=InnoDB;
CREATE TABLE drivers(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(150) NOT NULL,phone VARCHAR(30) NOT NULL,email VARCHAR(190),license_number VARCHAR(80),employment_type ENUM('daily','commission','contract') DEFAULT 'daily',daily_rate DECIMAL(10,2) DEFAULT 0,status ENUM('active','inactive','suspended') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(status)) ENGINE=InnoDB;
CREATE TABLE vehicles(id INT AUTO_INCREMENT PRIMARY KEY,vehicle_code VARCHAR(30) UNIQUE NOT NULL,vehicle_type ENUM('bicycle','tricycle','motorbike') NOT NULL,make_model VARCHAR(100),registration_number VARCHAR(60),payload_kg DECIMAL(8,2),status ENUM('available','assigned','maintenance','inactive') DEFAULT 'available',purchase_cost DECIMAL(12,2),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(status),INDEX(vehicle_type)) ENGINE=InnoDB;
CREATE TABLE deliveries(id INT AUTO_INCREMENT PRIMARY KEY,order_code VARCHAR(40) UNIQUE NOT NULL,customer_id INT NULL,customer_name VARCHAR(150) NOT NULL,customer_phone VARCHAR(30) NOT NULL,pickup_address TEXT NOT NULL,dropoff_address TEXT NOT NULL,vehicle_type ENUM('bicycle','tricycle','motorbike') NOT NULL,distance_km DECIMAL(8,2) NOT NULL,extra_stops INT DEFAULT 0,wait_minutes INT DEFAULT 0,rush TINYINT(1) DEFAULT 0,bulky TINYINT(1) DEFAULT 0,rain TINYINT(1) DEFAULT 0,total_price DECIMAL(10,2) NOT NULL,payment_method ENUM('cash','mobile_money','bank','invoice') DEFAULT 'cash',payment_status ENUM('unpaid','paid','partial') DEFAULT 'unpaid',notes TEXT,driver_id INT NULL,vehicle_id INT NULL,status ENUM('pending','assigned','picked_up','in_transit','delivered','cancelled') DEFAULT 'pending',created_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,assigned_at DATETIME,delivered_at DATETIME,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL,FOREIGN KEY(driver_id) REFERENCES drivers(id) ON DELETE SET NULL,FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(status),INDEX(created_at),INDEX(delivered_at)) ENGINE=InnoDB;
CREATE TABLE delivery_events(id INT AUTO_INCREMENT PRIMARY KEY,delivery_id INT NOT NULL,event_type VARCHAR(40) NOT NULL,description TEXT,created_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(delivery_id) REFERENCES deliveries(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE maintenance_records(id INT AUTO_INCREMENT PRIMARY KEY,vehicle_id INT NOT NULL,service_date DATE NOT NULL,maintenance_type VARCHAR(50) NOT NULL,description TEXT NOT NULL,cost DECIMAL(10,2) NOT NULL,odometer_km INT,next_service_date DATE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(vehicle_id) REFERENCES vehicles(id),INDEX(service_date)) ENGINE=InnoDB;
